python3 << 'EOF'
import fitz
d = fitz.open('src/MainPlot.pdf')
p = d[0]
draws = p.get_drawings()
for i in (1,3,7,14):
    dr = draws[i]
    pts = []
    for it in dr['items']:
        if it[0]=='l':
            pts.append(it[1]); pts.append(it[2])
        elif it[0]=='c':
            pts += [it[1],it[2],it[3],it[4]]
        elif it[0]=='re':
            pts.append(it[1].tl); pts.append(it[1].br)
    print('--- drawing',i, dr['type'], 'fill',dr['fill'],'closePath',dr.get('closePath'))
    for pt in pts:
        print(round(pt.x,2), round(pt.y,2))
EOF
